with open('backend/static_excel_data.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# The metrics to REMOVE
remove_names = [
    "Defects",
    "Defects/Journey",
    "Gross Abn%",
    "Duration - AHT",
    "Total Wait Time"
]

data['metrics'] = [m for m in data['metrics'] if m['name'] not in remove_names]

# Parse raw_data
raw_lines = [l.strip() for l in raw_data.strip().split('\n') if l.strip() and not l.startswith('Jan W1')]

new_metric_mapping = [
    "Avg. Wait Time",
    "Total Pax Impacted",
    "Cancellations Impact %",
    "Call Drop",
    "Blank Call",
    "Call Back (Call Drop + Blank Call)",
    "Call Drop Not Done",
    "Blank Call Not Done",
    "Overall Call Not Done",
    "Call Not Done %",
    "Call Received",
    "Answered",
    "Agent Disconnected",
    "Agent Disconnected %"
]

for idx, metric_name in enumerate(new_metric_mapping):
    if idx >= len(raw_lines):
        break
    line_parts = raw_lines[idx].split('\t')
    
    existing = next((m for m in data['metrics'] if m['name'] == metric_name), None)
    
    target_len = len(data['columns'])
    if len(line_parts) < target_len:
        line_parts.extend([''] * (target_len - len(line_parts)))
    elif len(line_parts) > target_len:
        line_parts = line_parts[:target_len]
        
    if existing:
        existing['values'] = line_parts
    else:
        data['metrics'].append({
            "name": metric_name,
            "values": line_parts
        })

with open('backend/static_excel_data.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, indent=2)

print("Patched JSON successfully!")
